                "\uD83D\uDC49“अच्छे लोगों की सबसे बड़ी खूबी यह होती है कि उन्हें याद रखना नहीं पड़ता, वो याद रह जाते है”❣",
                "\uD83D\uDC49“इंसान कहता हैं कि पैसा आये तो मैं कुछ कर के दिखाऊ और पैसा \uD83D\uDCB8कहता हैं कि तू कुछ कर तो मैं आऊं.”",
