                "\uD83D\uDC9Dआपकी मुस्कान हमारी कमज़ोरी है कह न पाना हमारी मज़बूरी है आप क्यों नहीं समझते इस ख़ामोशी को क्या ख़ामोशी को ज़ुबान देना ज़रूरी है।",
