                "❣प्यार वो एहसास है जो मिटता नहीं, प्यार वो पर्वत है जो झुकता नहीं प्यार की कीमत क्या है हमसे पूछो प्यार वो अनमोल हिरा है जो बिकता नही। Happy Valentine’s Day ❤",
                "\uD83D\uDC49तुम्हारे नाम को होठों पर सजाया है मैंने तुम्हारी रूह को दिल में बसाया है मैंने दुनिया आपको ढूंढते ढूंढते हो जाएगी पागल दिल के ऐसे कोने कोने में छुपाया है मैंने। \uD83D\uDC96",
                "\uD83D\uDC95बेवजह किसी को सताया नहीं करते हद से ज्यादा किसी को तड़पाया नहीं करते। आपके लफ्जों से, जिसकी सांस चलती है उन्हें इतना तरसाया नहीं करते। Happy Valentine Day \uD83D\uDE34",
