                "\uD83D\uDC49जन्मदिन के ये ख़ास लम्हें मुबारक, आँखों में बसे नए ख्वाब मुबारक, जिंदगी जो लेकर आई है आपके लिए आज.. वो तमाम खुशियों की हंसीं सौगात मुबारक! Happy Birthday\uD83C\uDF82\uD83C\uDF80",
                "\uD83D\uDC49ऐ खुदा एक मन्नत है हमारी, मेरी जान \uD83D\uDC9E जन्नत है हमारी,\uD83D\uDE18 चाहे हम हो ना हो साथ उनके, पर खुशियाँ मिले उनको प्यारी❣प्यारी… Happy Birthday \uD83D\uDE18 Jaan…\uD83C\uDF82",
                "\uD83D\uDC49एक दुआ \uD83D\uDE4F है कोई गिला नहीं हो, ऐसा प्यार \uD83D\uDC96 का फूल \uD83C\uDF3A जो आज तक खिला ना हो, आज मिले वो सब आपको, जो आज तक कभी किसी को मिला ना हो… \uD83C\uDF82H’py B’day to u\uD83C\uDF89",
                "\uD83D\uDC49ख्वाहिशों के समंदर के सब मोती तेरे नसीब हो, तेरे चाहने वाले हमसफ़र तेरे हरदम करीब हों, कुछ यूँ उतरे तेरे लिए रहमतों का मौसम, कि तेरी हर \uD83D\uDE4F दुआ, हर ख्वाहिश कबूल हो। \uD83C\uDF82जन्मदिन की बधाई!\uD83C\uDF82\uD83C\uDF80\uD83C\uDF81",
                "\uD83D\uDC49ये दुआ \uD83D\uDE4F है आपके जन्मदिन पे हमारी, ना तूटे कभी दोस्ती हमारी, सारी जिंदगी देंगे खुशियाँ आपको… और वो खुशियाँ होगी प्यारी प्यारी…\uD83D\uDE0A \uD83C\uDF82Happy Birthday to you my Best Friend…\uD83C\uDF82",
                "#Life का हर Goal रहे आपका Clear, तुम Success पाओ Without any #Fear हर \uD83D\uDE01पल जियो Without any #Tear, Enjoy your day my #Dear, \uD83C\uDF82HAPPY BIRTHDAY\uD83C\uDF82",
                "\uD83D\uDC49सूरज की रोशनी लेकर आया, और चिडियों ने गाना गाया… फूलों ने हंस हंस कर बोला… मुबारक हो तुम्हारा जन्मदिन आया… \uD83C\uDF82Happy Birthday\uD83C\uDF81",
                "\uD83D\uDC49ज़िंदगी की कुछ खास दुआएँ\uD83D\uDE4F ले लो हमसे जन्मदिन पर कुछ नजराने ले लो हमसे भर दे रंग जो तेरे जीवन के पलो में, आज वो हसी मुबारक बाद ले लो हमसे…\uD83C\uDF80\uD83C\uDF81",
                "\uD83D\uDC49On these Beautiful Birthday, भगवान करे आप Enjoyment से भरपूर और Smile से अपना आज का दिन Celebrate करो, और बहुत सारी Surprises पाओ,,, ^\uD83C\uDF82\uD83C\uDF80\uD83C\uDF81^HAPPY BIRTHDAY^\uD83C\uDF82^",
                "\uD83D\uDC49आसमान की बुलंदियों पर नाम हो आपका, चांद की धरती पर मुकाम हो आपका… हम तो रहते है छोटी-सी \uD83C\uDF0E दुनिया में, पर ईश्वर करें सारा जहान हो आपका… \uD83C\uDF82जन्मदिन की बहोत बहोत शुभकामनायें \uD83C\uDF81",
                "\uD83D\uDC49मैं लिख दू तुम्हारी उम्र चाँद सितारों से… मैं मनाऊ जन्मदिन तुम्हारा फूल बहारों से ऐसी खूबसूरती दुनिया \uD83C\uDF0E से लेकर आऊ मैं के सारी महफ़िल सज जाए हसीं नजारो से Happy \uD83C\uDF82 Birthday \uD83C\uDF82to You…\uD83C\uDF80\uD83C\uDF81",
                "\uD83D\uDC49दुनिया \uD83C\uDF0E कि सारी खुशियाँ मिले आपको, खुदा से रहमत और प्यार ❤ मिले आपको… आपके होठों पर बनी रहे हमेशा मुस्कान\uD83D\uDE0A, दुआ \uD83D\uDE4F है, उम्र के साथ साथ बढ़ते रहे आपका मान-सम्मान… ≛≛”•”•≛≛ \uD83C\uDF82“Happy Birthday”\uD83C\uDF80 ≛≛”•”•≛≛",
                "\uD83D\uDC49सूरज रोशनी लेकर आया और चिड़ियों ने भी गाना गाया… फूलोंने भी मुस्कुराया क्योंकि आज मेरा जन्मदिन है आया…\uD83D\uDE00",
                "\uD83D\uDC49पूरी हो दिल की हर ख्वाहिश आपके, मिले खुशियों का जहां आपको, अगर आप मांगें आसमां का एक तारा, तो खुदा दे दे सारा आसमां आपको। जन्मदिन की शुभकामनायें।\uD83E\uDD2D",
                "\uD83D\uDC49प्यार से भरी जिंदगी मिले आपको, खुशियाँ से भरे पल मिले आपको, कभी किसी ग़म का सामना ना करना पड़े, ऐसा आने वाला कल मिले आपको। जन्मदिन बहुत बहुत मुबारक।\uD83D\uDE01",
                "\uD83D\uDC49कैसे करूँ शुक्रिया उसका इस दिन के लिए❣, जिसने तुम्हें धरती पर भेजा हमारे लिए, इस जन्मदिन❤ पर कुछ और तो नहीं दे सकते, बस मेरी हर दुआ है तेरी लम्बी उम्र के लिए।",
                "\uD83D\uDC49हर दिन से प्यारा लगता है ये खास दिन, जिसे हम बिताना नहीं चाहते आप बिन, वैसे तो दिल देता है सदा ही दुआ आपको, फिर भी कहते हैं मुबारक हो जन्मदिन !!\uD83D\uDC93",

                "हर खुशी मिले इस जन्मदिन पर तुझे, दुआ है मेरी खुदा से हर कदम पर सफलता मिले तुझे।🎉",
                "तेरे चेहरे की ये मुस्कान सदा बनी रहे, हर जन्मदिन पर खुशियों की बारिश हो तेरे लिए।🌸",
                "दुआ करते हैं हम, तेरे इस जन्मदिन पर, हर ख्वाब पूरा हो जो तेरे दिल के अंदर है।🎂",
                "तेरे जीवन में आए खुशियों का सागर, जन्मदिन की बहुत-बहुत शुभकामनाएं मेरे प्यारे।🎁",
                "तेरी मुस्कान से रोशन है ये जहां, जन्मदिन पर यही दुआ है मेरी सदा रहे तू मेहरबां।✨",
                "तेरी हर सुबह खुशियों से भरी हो, जन्मदिन पर तेरी हर ख्वाहिश पूरी हो।💫",
                "हर साल ये दिन आए, खुशियों का तोहफा लाए, जन्मदिन की ढेर सारी बधाइयाँ।🎉",
                "खुशियों की फुलझड़ियाँ तेरे जीवन में चमकें, जन्मदिन पर तेरी हर मुराद पूरी हो।🎇",
                "तेरी मुस्कान मेरे लिए तोहफा है, जन्मदिन पर तेरे चेहरे पर ये चमक सदा रहे।😊",
                "तेरे जन्मदिन पर रब करे इतना करम, तेरे जीवन में रहे हमेशा खुशियों का संगम।🌟",
                "तेरे दिन खुशियों से महके, तेरी रातें प्यार से चमके। जन्मदिन मुबारक!🎂",
                "आज का दिन है तेरे नाम, रहे सदा तेरे चेहरे पर मुस्कान तमाम।🎈",
                "खुशियों से भरा रहे तेरा जीवन, जन्मदिन पर मिले सफलता का आशीर्वाद हर क्षण।🎊",
                "तेरे होंठों पर सदा मुस्कान रहे, जन्मदिन पर तेरे दिल की हर बात पूरी हो।💖",
                "तेरे जन्मदिन पर खुदा करे तुझे वो सब मिले जो तू चाहे।✨",
                "तेरे जीवन में कभी ना आए ग़म, हर साल जन्मदिन पर मिले नया कदम।🎉",
                "हर दिन तेरे लिए खास हो, जन्मदिन पर तुझे मिले दुनिया की हर आस।🌸",
                "जन्मदिन का ये प्यारा सा दिन, तुझे दे खुशियों का नया साज-संगीत।🎵",
                "तेरे जन्मदिन पर दिल से निकली ये दुआ, हर लम्हा तेरे लिए हो खुशियों से भरा।🌹",
                "हर साल तू करे प्रगति हजार गुना, जन्मदिन पर मिले तुझे खुशियों का खजाना।💫",
                "तेरे जन्मदिन पर है बस यही दुआ, मिले तुझे खुशियों की हर दास्ताँ।🎁",
                "जन्मदिन पर तेरे दिल से निकले खुशियों के रंग, तेरी हर सुबह हो उमंग से भरी।🌞",
                "तेरे आने से ज़िंदगी में रोशनी आई, जन्मदिन पर तुझे ढेरों बधाई।🌟",
                "खुदा करे हर साल तेरा जन्मदिन ऐसे ही प्यारा लगे, जैसे फूलों में खुशबू और सूरज में उजाला लगे।🌸",
                "हर सपना तेरा पूरा हो, जन्मदिन पर खुशियों का पहरा हो।🎂",
            )
        ),
        ShayariModel(
            "REPUBLIC DAY \uD83C\uDDEE\uD83C\uDDF3", listOf(
                "\uD83D\uDC49आज़ादी का जोश कभी कम ना होने देंगे जब भी ज़रूरत पड़ेगी देश के लिए जान लुटा देंगे क्योंकि भारत हमारा देश है अब दोबारा इस पर कोई आंच ना आने देंगे\uD83D\uDD7A",
                "\uD83D\uDC49वतन हमारा ऐसे ना छोड़ पाए कोई, रिश्ता हमारा ऐसे ना तोड़ पाए कोई, दिल हमारा एक है एक है हमारी जान. हिन्दुस्तान हमारा है हम है इसकी शान\uD83C\uDDEE\uD83C\uDDF3",
                "\uD83D\uDC49चलो फिर से खुद को जगाते हैं अनुशासन का डंडा फिर घुमाते हैं याद करें उन शूरवीरों को क़ुरबानी जिनके कारण हम इस लोकतंत्र का आनंद उठाते हैं\uD83C\uDDEE\uD83C\uDDF3❤",
                "\uD83D\uDC49ना पूछो ज़माने से कि क्या हमारी कहानी है हमारी पहचान तो बस इतनी है कि हम सब हिन्दुस्तानी हैं\uD83C\uDDEE\uD83C\uDDF3",
                "\uD83D\uDC49ना जियो धर्म के नाम पर, ना मरो धर्म के नाम पर, इंसानियत ही है धर्म वतन का बस जियों वतन के नाम पर\uD83C\uDDEE\uD83C\uDDF3❤",
                "\uD83C\uDDEE\uD83C\uDDF3कुछ नशा तिरंगे की आन है कुछ नशा मातृभूमि की शान का है हम लहराएँगे हर जगह ये तिरंगा नशा ये हिंदुस्तान की शान का है\uD83C\uDDEE\uD83C\uDDF3",
                "\uD83D\uDC49देश भक्तो की बलिदान से स्वतंत्रा हुए है हम कोई पूछे कोन हो तो गर्व से कहेंगे भारतीय है हम \uD83C\uDDEE\uD83C\uDDF3",
                "\uD83D\uDC49याद रखेंगे वीरो तुमको हरदम, यह बलिदान तुम्हारा है, हमको तो है जान से प्यारा यह गणतंत्र हमारा है \uD83C\uDDEE\uD83C\uDDF3\uD83C\uDFC7",
                "\uD83E\uDEC2अलग है भाषा, धर्म जात, और प्रांत, भेष, परिवेश, पर हम सब का एक ही गौरव है, राष्ट्रध्वज तिरंगा श्रेठ\uD83C\uDDEE\uD83C\uDDF3",
                "वतन हमारा मिसाल मोहब्बत की, तोड़ता है दीवार नफरत की, मेरी खुशनसीबी है मैं इस मिट्टी का कण हूँ, जो महक उठी ख़ुशबू शहादत की।🇮🇳",
                "ना पूछो ज़माने से कि क्या हमारी कहानी है, हमारी पहचान तो बस इतनी है कि हम हिंदुस्तानी हैं।❤️🇮🇳",
                "तिरंगा हमारी शान है, हिंदुस्तान हमारा अभिमान है। जय हिन्द!🇮🇳",
                "देश भक्तों की बलिदान से मिली ये आज़ादी, हम सबको इसे मिलकर सजाना है। गणतंत्र दिवस की शुभकामनाएं।🎉",
                "खुशनसीब हैं वो जो वतन पर मिट गए, चलो आज उन्हें श्रद्धांजलि अर्पण करें।🇮🇳",
                "वो शमा जो काम आए वतन के लिए, वो दिल जो धड़कता है देश के लिए। जय हिन्द!✨",
                "हमारा तिरंगा कभी झुक ना पाए, यही अरमान दिल में समाए। गणतंत्र दिवस मुबारक।🎆",
                "देशभक्ति की भावना हर दिल में हो, चलो मिलकर इस गणतंत्र दिवस को खास बनाएं।🇮🇳",
                "मेरा भारत महान है, इसकी शान तिरंगा है। जय हिन्द जय भारत।🎇",
                "सिर्फ एक दिन नहीं, हर दिन तिरंगे को सलाम करो। यही सच्ची देशभक्ति है।🇮🇳",
                "ना सरकार मेरी है, ना रौब मेरा है, बस एक छोटा सा हिन्दुस्तान मेरा है।🇮🇳",
                "सरफ़रोशी की तमन्ना अब हमारे दिल में है, देखना है ज़ोर कितना बाज़ू-ए-क़ातिल में है।💪",
                "जिस देश में गंगा बहती है, वो देश मेरा प्यारा भारत है।💧🇮🇳",
                "गणतंत्र दिवस का त्योहार है आया, सबके दिल में जोश और गर्व जगाया।🇮🇳",
                "दिल दिया है जान भी देंगे, ऐ वतन तेरे लिए।❤️🇮🇳",
                "सैनिकों की शहादत को मत भूलो, ये आज़ादी उन्हीं की बदौलत है।🙏",
                "गणतंत्र दिवस पर यही पैगाम है, हम सब एक हैं और यही हमारी पहचान है।🇮🇳",
                "तिरंगे की शान में सब झुक जाएं, ऐसा गणतंत्र दिवस हर साल आए।🎉",
                "चलो आज फिर वो नज़ारा याद करें, शहीदों के बलिदान को सलाम करें।🙏🇮🇳",
                "भारत माता की जय कहने का हक़ उन्हीं को है, जो दिल से इस मिट्टी को पूजते हैं।🌾",
                "देशभक्ति की भावना दिल में बसाओ, तिरंगे को दिल से अपनाओ।🇮🇳",
                "वो सुबह कभी तो आएगी, जब कोई हिन्दू-मुसलमान ना कहेगा, बस हिन्दुस्तानी कहेगा।🤝🇮🇳",
                "ना जियो धर्म के नाम पर, ना मरो धर्म के नाम पर, इंसानियत ही धर्म है, जियो वतन के नाम पर।✨",
                "देश की रक्षा में जिनका लहू बहा, उन वीरों को मेरा सलाम।🙏🇮🇳",
                "आजादी का जो मज़ा है, वो सिर्फ हिन्दुस्तान में ही है।🎆",
