        ShayariModel(
            "DIWALI \uD83E\uDE94", listOf(
                "\uD83D\uDC49गुल ने गुलशन से गुलफाम भेजा है, सितारों ने गगन से सलाम भेजा है, मुबारक हो आपको यह दिवाली, हमने तहे दिल से सलाम भेजा है…\uD83E\uDE94 ",
                "\uD83D\uDC49जगमग थाली सजाओ मंगल दीपो को जलाओ अपने घरों और दिलों मैं आशा की किरण जगाओ खुशियाँ और समृधि से भरा हों आपका जीवन इसी कामना के साथ शुभ दीपावली |\uD83E\uDE94",
                "\uD83D\uDC49एक दुआ मांगते है……, हम अपने भगवान से, चाहते है आपकी ख़ुशी पुरे ईमान से, सब हसरतें पूरी हो आपकी, और आप…… मुस्कुराएं दिल-ओ-जान सें……|❤",
                "\uD83D\uDC49पटाखो की आवाज़ से गूंज रहा संसार, दीपक की रोशनी, ओर अपनो का प्यार, मुबारक हो आपको दिवाली का त्योहार|\uD83E\uDE94",
                "\uD83D\uDC49हो मुबारक ये त्यौहार आपको दीपावली का ज़िन्दगी का हर पल मिले आपको खुशहाली का प्यार के जुगनू जले, प्यार की हो फुलझड़िया प्यार के फूल खिले, प्यार की हो पंखुड़िया प्यार की बंसी बजे, प्यार की हो शहनाईया… खुशियो के दीप जले, दुःख कभी न ले अंगड़ाईयां❤\uD83D\uDCAF\uD83E\uDE94",
                "\uD83E\uDE94हर घर में दिवाली हो, हर घर में दिया जले जब तक ये रहे दुनिया जब तक संसार चले दुःख, दर्द, उदासी से हर दिल महरूम रहे पग पग उजियालो में जीवन की ज्योति जले\uD83E\uDE94",
                "\uD83E\uDE94श्री राम जी आपके संसार में सुख की बरसात करें, और दुखों का नाश करें प्रेम की फुलझड़ी से आपका घर आंगन रौशन हो\uD83C\uDF19",
                "\uD83D\uDC49\uD83E\uDE94दीपावली आए तो रंगी रंगोली, दीप जलाए, धूम धड़ाका, छोड़ा पटाखा, जली फुलझडि़यां सबको भाए.. आप सबको दीपावली की शुभकामनाएं!\uD83E\uDE94",
                "\uD83D\uDC49रोशन हो दीपक और सारा जग जगमगाये लिए साथ सीता मैय्या को राम जी हैं लाये हर शहर यूँ लगे मानो अयोधया हो आओ हर द्वार हर गली हर मोड़ पे हम दीप जलाये\uD83E\uDE94",
                "हमेशा मीठी रहे आपकी बोली खुशियों से भर जाए आपकी झोली आप सबको मेरी तरफ से हैप्पी Diwali \uD83E\uDE94",
                "\uD83D\uDC49दिलों को मिलाने का मौसम है दूरियां मिटाने का मौसम है दिवाली का त्यौहार ही ऐसा है खुशी में डूब जाने का मौसम है Happy Diwali \uD83C\uDF87",
                "\uD83E\uDE94कदम-कदम पर खुशियां रहें, गम से कभी ना हो सामना, जिंदगी में हर पल खुशियां नसीब हों मेरी तरफ से दिवाली की हार्दिक शुभकामना।",
                "मिठाइयों का हो ओवर फ्लो मस्ती हो कभी ना लो मिठाई और पटाखे का सुरूर छाया रहे पॉकेट में भरी माया रहे गुड लक की हो बौछार आया दिवाली का त्यौहार \uD83E\uDE94",
                "\uD83D\uDC49हवाओं के साथ अरमान भेजा है, नेटवर्क के जरिये पैगाम भेजा है, वो हम हैं, जिसने सबसे पहले, दिवाली का राम-राम भेजा है। Happy diwali \uD83C\uDF87",
                "दीप जलते रहे मन में उजाला रहे, हर दिन तुम्हारा खुशियों वाला रहे।✨🪔",
